// p-arm check on :5284: a solid barrier arm blocking a walker (3D), and the gripper needing the right pose (between-fingers rule, 3D).
// Boards are generated by the scratchpad mkboards.mjs (JSON files opened through File > Mo file). Shots go to plans/reports/shots-p-arm/.
const { chromium } = await import('file:///C:/Users/trong/AppData/Local/Temp/claude/a12094c0c35d488c/21dd1524-bf64-49b0-bdae-47a5b1b986a8/scratchpad/smoke/node_modules/playwright/index.mjs');
import fs from 'node:fs';
const OUT = 'D:/workspace/GameBuilder/plans/reports/shots-p-arm/';
const BOARDS = 'C:/Users/trong/AppData/Local/Temp/claude/a12094c0c35d488c/59c556cb-2e9f-4c7a-9d77-47346d462571/scratchpad/boards/';
fs.mkdirSync(OUT, { recursive: true });
const BASE = 'http://localhost:5284';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const b = await chromium.launch({ executablePath: 'C:/Users/trong/AppData/Local/ms-playwright/chromium-1248/chrome-win64/chrome.exe', args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--enable-webgl'] });
const logs = [];
const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
p.on('pageerror', (e) => logs.push(`pageerror: ${e.message}`));
p.on('console', (m) => { if (m.type() === 'error') logs.push(m.text()); });

async function fresh() {
  await p.goto(`${BASE}/`);
  await sleep(1500);
  await p.evaluate(() => localStorage.clear());
  await p.reload();
  await sleep(1500);
  if (await p.locator('[data-tut="invite-no"]').isVisible().catch(() => false)) { await p.locator('[data-tut="invite-no"]').click(); await sleep(300); }
}
async function openFile(name) {
  await p.locator('[data-menu="file"]').click(); await sleep(200);
  const chooser = p.waitForEvent('filechooser');
  await p.locator('.mb-item', { hasText: 'Mở file' }).first().click();
  await (await chooser).setFiles(BOARDS + name + '.json');
  await sleep(1200);
}
async function play() {
  await p.locator('.play .pbtn.primary').click();
  await sleep(1200);
  // enlarge the floating preview so the scene is readable
  await p.mouse.click(1126, 398);
  await sleep(1200);
}
const crop = { x: 0, y: 0, width: 1440, height: 900 };
async function zshot(name) { await p.screenshot({ path: OUT + name + '.png', clip: crop }); }

const only = process.env.ONLY ?? 'all';
if (only === 'all' || only === 'barrier') {
  for (const name of ['barrier-down', 'barrier-up']) {
    await fresh();
    await openFile(name);
    await p.screenshot({ path: OUT + `${name}-editor.png` });
    await play();
    await sleep(1500);
    await zshot(`${name}-1s`);
    await sleep(3500);
    await zshot(`${name}-5s`);
  }
}
if (only === 'all' || only === 'grip') {
  for (const name of ['grip-right', 'grip-wrong']) {
    await fresh();
    await openFile(name);
    await play();
    await sleep(1500);
    await zshot(`${name}-0-before`);
    await p.keyboard.down('Space');
    await sleep(1800);
    await zshot(`${name}-1-space-held`);
    await p.keyboard.up('Space');
  }
}
console.log('LOGS', JSON.stringify(logs));
await b.close();
